// Generated by vibelang from worker/personal/Defaults.vibe; the migrate flow writes it again with each batch.
import * as Effect_1 from "effect/Effect";
import { Config, Effect } from "effect";
import { DEFAULTS } from "../../src/features/personal-model/contract.js";
// What a connection kind fills in for the person (decision 0132). Choices are configuration (SDK-9), named for what they
// are: another deployment points Kimi at a regional endpoint, or a later model, with no code change.
/**
 * `MOONSHOT_BASE_URL` and `MOONSHOT_MODEL`: the endpoint a `moonshot` connection goes to and the model its tiers use,
 * Moonshot's international endpoint and Kimi K3 unless set (platform.moonshot.ai/docs/api/chat, read 2026-10-31).
 */
export const connectionDefaults = Effect.orDie(Effect_1.gen(function* () {
    const baseUrl = yield* Config.String("MOONSHOT_BASE_URL").pipe(Config.withDefault(DEFAULTS.moonshot.baseUrl));
    const modelId = yield* Config.String("MOONSHOT_MODEL").pipe(Config.withDefault(DEFAULTS.moonshot.modelId));
    return { moonshot: { baseUrl, modelId } };
}));
